import { useEffect, useState } from "react";
import { Box, Button, Typography } from "@mui/material";
import api from "../services/api";
import type { HomeCta, SingleResponse } from "../types/home";

export default function ExamCta() {
  const [data, setData] = useState<HomeCta | null>(null);

  useEffect(() => {
    api
      .get<SingleResponse<HomeCta>>("/home-cta")
      .then((payload) => setData(payload.data || null))
      .catch(() => setData(null));
  }, []);

  if (!data) return null;

  return (
    <Box sx={{ textAlign: "center", py: 6 }}>
      <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 36 }, fontWeight: 600, mb: 3 }}>
        {data.title}
      </Typography>
      {data.buttonUrl ? (
        <Button
          variant="contained"
          href={data.buttonUrl}
          sx={{
            backgroundColor: "#759ae1",
            px: 4,
            py: 1.2,
            borderRadius: "6px",
            "&:hover": { backgroundColor: "#5f86d4" },
          }}
        >
          {data.buttonLabel || "Subscribe Now"}
        </Button>
      ) : null}
    </Box>
  );
}
